<script lang="ts">
 import Icon from './Icon.svelte';
 let {localStorage=false}:{localStorage?:boolean}=$props();
 import {onMount} from 'svelte';
 import {upload} from '@vercel/blob/client';
 import type {IconName} from '../lib/icons';
 const tabs: {value:string;label:string;icon:IconName}[]=[{value:'news',label:'Berita',icon:'newspaper'},{value:'magazines',label:'Majalah',icon:'book-open'},{value:'media',label:'Pustaka media',icon:'images'},{value:'settings',label:'Pengaturan',icon:'settings'}];
 let tab=$state('news');let items=$state<any[]>([]);let media=$state<any[]>([]);let error=$state('');let message=$state('');let busy=$state(false);let progress=$state<number|null>(null);let editing=$state<any>(null);let confirmId=$state('');let editor=$state<HTMLDivElement>(null!);
 const blank=()=>tab==='news'?{title:'',category:'Kehidupan Sekolah',excerpt:'',author:'Redaksi Sekolah',content:'<p></p>',featuredImageUrl:'',status:'draft'}:{title:'',edition:'',year:new Date().getFullYear(),description:'',coverUrl:'',pdfUrl:'',allowDownload:true,status:'draft'};
 async function request(path:string,options?:RequestInit){const res=await fetch(path,options);if(res.status===401){location.href='/adminlog';throw Error('Sesi berakhir');}const data=await res.json();if(!res.ok)throw Error(data.error||'Permintaan gagal');return data;}
 async function load(){busy=true;error='';try{if(tab==='media')media=await request('/api/admin/media');else if(tab!=='settings')items=await request(`/api/admin/content?kind=${tab}`);}catch(e){error=String(e instanceof Error?e.message:e);}finally{busy=false;}}
 async function switchTab(value:string){tab=value;editing=null;message='';confirmId='';await load();}
 function edit(item:any=null){editing=item?structuredClone(item):blank();error='';message='';}
 async function save(status:string){if(!editing)return;busy=true;error='';try{if(tab==='news')editing.content=editor.innerHTML;const result=await request(`/api/admin/content?kind=${tab}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...editing,status})});editing=null;await load();message=status==='published'?`“${result.title}” telah diterbitkan.`:'Draft berhasil disimpan.';}catch(e){error=e instanceof Error?e.message:'Gagal menyimpan';}finally{busy=false;}}
 async function remove(item:any){busy=true;try{await request(`/api/admin/content?kind=${tab}`,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:item.id,updatedAt:item.updatedAt})});confirmId='';await load();message='Konten dihapus. Media dipertahankan hingga dibersihkan secara manual.';}catch(e){error=e instanceof Error?e.message:'Gagal menghapus';}finally{busy=false;}}
 async function removeMedia(item:any){busy=true;try{await request('/api/admin/media',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:item.url})});confirmId='';await load();message='Media dihapus.';}catch(e){error=e instanceof Error?e.message:'Gagal menghapus';}finally{busy=false;}}
 async function localUpload(file:File):Promise<{url:string}>{
  const form=new FormData();form.append('file',file);
  return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/admin/upload');xhr.upload.onprogress=e=>{if(e.lengthComputable)progress=Math.round(e.loaded/e.total*100);};xhr.onerror=()=>reject(Error('Koneksi unggahan terputus.'));xhr.onload=()=>{try{const data=JSON.parse(xhr.responseText);if(xhr.status<200||xhr.status>=300)throw Error(data.error||'Unggah gagal');resolve(data);}catch(e){reject(e);}};xhr.send(form);});
 }
 async function fileChanged(e:Event,field:string){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;const pdf=field==='pdfUrl';if(!(pdf?['application/pdf']:['image/jpeg','image/png','image/webp']).includes(file.type)||file.size>(pdf?50:5)*1024*1024){error=`Format tidak sesuai atau ukuran melebihi ${pdf?50:5} MB.`;return;}busy=true;error='';progress=0;try{const ext=({'image/jpeg':'jpg','image/png':'png','image/webp':'webp','application/pdf':'pdf'} as Record<string,string>)[file.type];const blob=localStorage?await localUpload(file):await upload(`media/${crypto.randomUUID()}.${ext}`,file,{access:'public',handleUploadUrl:'/api/admin/upload',multipart:pdf,clientPayload:JSON.stringify({type:file.type}),onUploadProgress:p=>progress=Math.round(p.percentage)});let verified=false;for(let i=0;i<20;i++){const state=await request(`/api/admin/media?url=${encodeURIComponent(blob.url)}&type=${pdf?'pdf':'image'}`);if(state.ready){verified=true;break;}await new Promise(r=>setTimeout(r,1000));}if(!verified)throw Error('Validasi unggahan belum selesai. Coba ulang setelah beberapa saat.');if(field==='inline'){editor.focus();document.execCommand('insertHTML',false,`<img src="${blob.url}" alt="Gambar artikel"/>`);}else editing[field]=blob.url;if(pdf)editing.fileSize=file.size;message='Unggahan selesai dan format terverifikasi.';}catch(e){error=e instanceof Error?e.message:'Unggah gagal';}finally{busy=false;progress=null;}}
 function format(command:string,value?:string){editor.focus();document.execCommand(command,false,value);}
 function paste(e:ClipboardEvent){e.preventDefault();document.execCommand('insertText',false,e.clipboardData?.getData('text/plain')||'');}
 let link=$state('');let showLink=$state(false);
 function insertLink(){if(/^https:\/\//.test(link)){format('createLink',link);showLink=false;link='';}else error='Tautan harus diawali https://';}
 async function logout(){busy=true;error='';try{await request('/api/admin/logout',{method:'POST'});location.href='/adminlog';}catch(e){error=e instanceof Error?e.message:'Gagal keluar. Coba lagi.';}finally{busy=false;}}
 onMount(()=>{void load();});
</script>
<div class="admin-shell"><aside><div class="eyebrow">Ruang redaksi</div><h2>Kelola cerita.</h2>{#each tabs as {value,label,icon}}<button class:active={tab===value} disabled={busy} onclick={()=>switchTab(value)}><span class="admin-tab-label"><Icon name={icon}/>{label}</span><Icon name="chevron-right" size={16}/></button>{/each}<button disabled={busy} onclick={logout}><span class="admin-tab-label"><Icon name="log-out"/>Keluar</span></button></aside><section class="workspace"><div class="admin-title"><div><div class="eyebrow">Dashboard admin</div><h2>{tab==='news'?'Berita sekolah':tab==='magazines'?'Majalah digital':tab==='media'?'Pustaka media':'Pengaturan'}</h2></div>{#if ['news','magazines'].includes(tab)&&!editing}<button class="button" disabled={busy} onclick={()=>edit()}>Tambah {tab==='news'?'berita':'majalah'} <Icon name="plus"/></button>{/if}</div>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if message}<p class="success" role="status">{message}</p>{/if}{#if progress!==null}<label class="field">Mengunggah & memvalidasi: {progress}%<progress value={progress} max="100"></progress></label>{/if}
{#if tab==='settings'}<div class="notice">Profil sekolah dikelola dari <code>src/lib/school.ts</code> dan memerlukan deployment ulang.</div><h3 class="settings-title">Konfigurasi & penyimpanan</h3>{#if localStorage}<p>Mode lokal: berita, majalah, dan file tersimpan di folder .data pada komputer ini.</p>{:else}<p>Berita dan majalah disimpan sebagai JSON terpisah dalam private Vercel Blob. Foto dan PDF disimpan dalam public Vercel Blob.</p>{/if}<p>Username, hash password, dan secret sesi diatur melalui environment variables di Vercel. Ubah SESSION_SECRET untuk mencabut seluruh sesi aktif.</p><p>PDF yang sudah dipublikasikan tetap dapat disalin meskipun tombol unduh dinonaktifkan.</p>
{:else if tab==='media'}<p class="muted">Hapus hanya media yang tidak digunakan. File yang masih dirujuk berita atau majalah akan dipertahankan.</p><div class="media-grid">{#each media as m}<article>{#if m.type.startsWith('image/')}<img src={m.url} alt="Media unggahan" width="200" height="150"/>{:else}<div class="pdf-icon">PDF</div>{/if}<p>{m.pathname}</p><a href={m.url} target="_blank" rel="noopener noreferrer">Buka <Icon name="arrow-up-right"/></a>{#if confirmId===m.url}<button onclick={()=>removeMedia(m)} disabled={busy}>Ya, hapus permanen</button><button onclick={()=>confirmId=''}>Batal</button>{:else}<button onclick={()=>confirmId=m.url}><Icon name="trash-2" size={16}/> Hapus</button>{/if}</article>{/each}</div>{#if !busy&&!media.length}<div class="empty">Belum ada media terunggah.</div>{/if}
{:else if editing}<form onsubmit={(e)=>{e.preventDefault();save('published');}}><div class="editor-heading"><span class="pill">{editing.id?'Edit konten':'Konten baru'}</span><button type="button" class="text-button" disabled={busy} onclick={()=>editing=null}>Tutup <Icon name="x"/></button></div><label class="field">Judul<input bind:value={editing.title} required minlength="3" maxlength="180"/></label>{#if tab==='news'}<div class="row"><label class="field">Kategori<input bind:value={editing.category} required maxlength="80"/></label><label class="field">Penulis<input bind:value={editing.author} required maxlength="100"/></label></div><label class="field">Ringkasan<textarea bind:value={editing.excerpt} required minlength="10" maxlength="500"></textarea></label><label class="field">Gambar utama (JPG, PNG, WebP · maks. 5 MB)<input type="file" accept="image/jpeg,image/png,image/webp" disabled={busy} onchange={e=>fileChanged(e,'featuredImageUrl')}/></label>{#if editing.featuredImageUrl}<img class="uploaded" src={editing.featuredImageUrl} alt="Gambar utama"/>{/if}<div class="field"><span id="content-label">Isi artikel</span><div class="editor-toolbar" role="toolbar" aria-label="Format artikel" tabindex="0">{#each [{command:'bold',label:'Tebal',icon:'bold',value:''},{command:'italic',label:'Miring',icon:'italic',value:''},{command:'formatBlock',label:'Judul 2',icon:'heading-2',value:'h2'},{command:'formatBlock',label:'Judul 3',icon:'heading-3',value:'h3'},{command:'formatBlock',label:'Paragraf',icon:'pilcrow',value:'p'},{command:'insertUnorderedList',label:'Daftar poin',icon:'list',value:''},{command:'insertOrderedList',label:'Daftar bernomor',icon:'list-ordered',value:''},{command:'formatBlock',label:'Kutipan',icon:'quote',value:'blockquote'}] as {command,label,icon,value}}<button type="button" onmousedown={e=>e.preventDefault()} title={label} aria-label={label} onclick={()=>format(command,value)}><Icon name={icon as IconName} size={18}/></button>{/each}<button type="button" onmousedown={e=>e.preventDefault()} aria-expanded={showLink} onclick={()=>showLink=!showLink}><Icon name="link" size={16}/> Tautan</button></div>{#if showLink}<div class="row"><input bind:value={link} aria-label="URL tautan" placeholder="https://"/><button type="button" onclick={insertLink}>Sisipkan tautan</button></div>{/if}<div class="rich-editor prose" bind:this={editor} contenteditable="true" role="textbox" aria-multiline="true" aria-labelledby="content-label" onpaste={paste}>{@html editing.content}</div><label class="field">Sisipkan gambar dalam artikel<input type="file" accept="image/jpeg,image/png,image/webp" disabled={busy} onchange={e=>fileChanged(e,'inline')}/></label></div>{:else}<div class="row"><label class="field">Edisi<input bind:value={editing.edition} required maxlength="40"/></label><label class="field">Tahun<input type="number" bind:value={editing.year} min="1900" max="2200" required/></label></div><label class="field">Deskripsi<textarea bind:value={editing.description} maxlength="4000"></textarea></label><label class="field">Cover (JPG, PNG, WebP · maks. 5 MB)<input type="file" accept="image/jpeg,image/png,image/webp" disabled={busy} onchange={e=>fileChanged(e,'coverUrl')}/></label>{#if editing.coverUrl}<img class="uploaded" src={editing.coverUrl} alt="Cover majalah"/>{/if}<label class="field">Dokumen PDF (maks. 50 MB)<input type="file" accept="application/pdf" disabled={busy} onchange={e=>fileChanged(e,'pdfUrl')}/></label>{#if editing.pdfUrl}<p class="success">PDF telah terunggah.</p>{/if}<label class="checkbox"><input type="checkbox" bind:checked={editing.allowDownload}/> Tampilkan tombol unduh PDF</label>{/if}<div class="save-actions"><button class="button light" type="button" onclick={()=>save('draft')} disabled={busy}>Simpan draft <Icon name="save" size={18}/></button><button class="button" type="submit" disabled={busy}>Terbitkan <Icon name="send" size={18}/></button></div></form>
{:else}{#if busy}<p role="status">Memuat konten…</p>{:else if !items.length}<div class="empty"><h3>Cerita pertama dimulai di sini.</h3><p>Tambahkan konten, simpan draft, lalu terbitkan saat siap.</p></div>{/if}<div class="content-list">{#each items as item}<article><div><span class="pill">{item.status==='published'?'Terbit':'Draft'}</span><h3>{item.title}</h3><p class="muted">{new Date(item.updatedAt).toLocaleDateString('id-ID')}</p></div><div class="list-actions">{#if item.status==='published'}<a href={`/${tab==='news'?'berita':'majalah'}/${item.slug}`} target="_blank" rel="noopener noreferrer">Lihat <Icon name="arrow-up-right"/></a>{/if}<button onclick={()=>edit(item)} disabled={busy}><Icon name="pencil" size={16}/> Edit</button>{#if confirmId===item.id}<button onclick={()=>remove(item)} disabled={busy}>Ya, hapus</button><button onclick={()=>confirmId=''}>Batal</button>{:else}<button onclick={()=>confirmId=item.id} disabled={busy}><Icon name="trash-2" size={16}/> Hapus</button>{/if}</div></article>{/each}</div>{/if}</section></div>
<style>.admin-shell{display:grid;grid-template-columns:210px minmax(0,1fr);gap:45px;padding:50px 0 80px}aside{border-right:1px solid #cccdbf;padding-right:25px}aside h2{font-size:28px}aside>button{display:flex;justify-content:space-between;width:100%;border:0;border-bottom:1px solid #cccdbf;background:transparent;padding:17px 10px;font-size:12px}.active{background:#e0e4d5!important}.admin-title{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:25px}.admin-title h2{font-size:36px;margin:0}.admin-title .eyebrow{margin-bottom:12px}.row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.editor-heading,.save-actions{display:flex;justify-content:space-between;gap:15px;margin:25px 0}.text-button{background:none;border:0}.editor-toolbar{display:flex;gap:5px;flex-wrap:wrap}.editor-toolbar button,.list-actions button,.media-grid button{background:transparent;border:1px solid #a3a991;padding:7px 12px;font-size:11px}.rich-editor{background:#fffdf8;border:1px solid #b8b9a9;padding:20px;min-height:300px;width:100%;font-size:14px;max-height:650px;overflow:auto}.uploaded{max-height:180px;max-width:220px;margin-bottom:20px}.checkbox{display:flex;align-items:center;gap:10px}.checkbox input{width:auto}.content-list article{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #cccdbf;padding:25px 0;gap:25px}.content-list h3{margin:12px 0}.content-list p{font-size:10px;margin:0}.list-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;font-size:11px}.settings-title{margin-top:35px}.workspace>p{font-size:12px}.media-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.media-grid img{height:150px;width:100%}.media-grid p{overflow-wrap:anywhere;font-size:10px}.media-grid article{border:1px solid #cccdbf;padding:12px}.media-grid a{display:block;margin:10px 0;font-size:11px}.pdf-icon{height:150px;display:grid;place-items:center;background:#e0e4d5;font:30px var(--font-display)}@media(max-width:1000px){.admin-shell{grid-template-columns:1fr;gap:30px;padding-top:30px}aside{border-right:0;padding:0}aside>button{display:inline-flex;width:auto;gap:20px;padding:13px}aside .eyebrow,aside h2{display:none}.admin-title{align-items:start;flex-direction:column}.row{grid-template-columns:1fr;gap:0}.content-list article{flex-direction:column;align-items:start}.media-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.save-actions{flex-wrap:wrap}}
.workspace,.workspace form,.row>*,.content-list article>div{min-width:0}
.admin-tab-label{display:inline-flex;align-items:center;gap:10px}
.editor-toolbar button,.list-actions button,.media-grid button{display:inline-flex;align-items:center;justify-content:center;gap:6px}
.editor-toolbar button,.list-actions button,.media-grid button,.media-grid a,aside>button{min-height:44px}
.editor-toolbar button{min-width:44px}
.list-actions a{display:inline-flex;align-items:center;min-height:44px}
.content-list article>div:first-child{flex:1}
.list-actions{flex-shrink:0;max-width:100%}
.content-list h3,.rich-editor,.media-grid p{overflow-wrap:anywhere}
input[type=file]{max-width:100%;font-size:12px}
progress{width:100%;max-width:100%}
@media(min-width:1001px) and (max-width:1200px){.admin-shell{grid-template-columns:180px minmax(0,1fr);gap:25px}.media-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.content-list article{flex-wrap:wrap}}
@media(min-width:601px) and (max-width:1000px){.row{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.media-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:480px){.media-grid{grid-template-columns:minmax(0,1fr)}.admin-title h2{font-size:30px}.save-actions{flex-direction:column}.save-actions .button{width:100%}.admin-title>.button{width:100%}aside>button{font-size:11px;padding-inline:10px;gap:12px}}
</style>
